package com.acme.salary;
import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api") @CrossOrigin(origins="http://localhost:5173")
public class SalaryController{
 private final JdbcTemplate db;public SalaryController(JdbcTemplate db){this.db=db;}
 public record EmployeeInput(@NotBlank String employeeNumber,@NotBlank String firstName,@NotBlank String lastName,@Email @NotBlank String email,@NotBlank String country,@NotBlank String department,@NotBlank String jobTitle,@NotBlank String employmentStatus){}
 public record SalaryInput(@NotNull @DecimalMin("0.0") BigDecimal amount,@NotNull @DecimalMin("0.0") BigDecimal bonus,@NotBlank @Size(min=3,max=3) String currency,@NotNull LocalDate effectiveDate,@NotBlank String reason){}
 @GetMapping("/employees") public Map<String,Object> employees(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="") String country,@RequestParam(defaultValue="") String department){
  int p=Math.max(0,page),s=Math.min(100,Math.max(1,size));String where=" WHERE (?='' OR lower(first_name||' '||last_name||' '||email||' '||employee_number) LIKE ?) AND (?='' OR country=?) AND (?='' OR department=?)";String term="%"+search.toLowerCase(Locale.ROOT)+"%";
  Integer total=db.queryForObject("SELECT COUNT(*) FROM employee"+where,Integer.class,search,term,country,country,department,department);
  List<Map<String,Object>> rows=db.queryForList("SELECT e.*,s.amount AS salary,s.currency,s.bonus,s.effective_date FROM employee e LEFT JOIN salary_record s ON s.id=(SELECT id FROM salary_record WHERE employee_id=e.id ORDER BY effective_date DESC,id DESC LIMIT 1)"+where+" ORDER BY e.id LIMIT ? OFFSET ?",search,term,country,country,department,department,s,p*s);
  return Map.of("items",rows,"page",p,"size",s,"total",total==null?0:total,"totalPages",(int)Math.ceil((total==null?0:total)/(double)s));
 }
 @GetMapping("/employees/{id}") public Map<String,Object> employee(@PathVariable long id){Map<String,Object> e=db.queryForMap("SELECT * FROM employee WHERE id=?",id);e.put("salaryHistory",db.queryForList("SELECT * FROM salary_record WHERE employee_id=? ORDER BY effective_date DESC,id DESC",id));return e;}
 @PostMapping("/employees") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> create(@Valid @RequestBody EmployeeInput x){db.update("INSERT INTO employee(employee_number,first_name,last_name,email,country,department,job_title,employment_status) VALUES(?,?,?,?,?,?,?,?)",x.employeeNumber(),x.firstName(),x.lastName(),x.email(),x.country(),x.department(),x.jobTitle(),x.employmentStatus());return Map.of("message","Employee created");}
 @PutMapping("/employees/{id}") public Map<String,String> update(@PathVariable long id,@Valid @RequestBody EmployeeInput x){require(id);db.update("UPDATE employee SET employee_number=?,first_name=?,last_name=?,email=?,country=?,department=?,job_title=?,employment_status=? WHERE id=?",x.employeeNumber(),x.firstName(),x.lastName(),x.email(),x.country(),x.department(),x.jobTitle(),x.employmentStatus(),id);return Map.of("message","Employee updated");}
 @DeleteMapping("/employees/{id}") public Map<String,String> deactivate(@PathVariable long id){require(id);db.update("UPDATE employee SET employment_status='INACTIVE' WHERE id=?",id);return Map.of("message","Employee deactivated");}
 @PutMapping("/employees/{id}/salary") public Map<String,String> salary(@PathVariable long id,@Valid @RequestBody SalaryInput x){require(id);SalaryRules.validate(x.amount(),x.bonus(),x.currency(),x.effectiveDate(),x.reason());db.update("INSERT INTO salary_record(employee_id,amount,currency,bonus,effective_date,reason) VALUES(?,?,?,?,?,?)",id,x.amount(),x.currency().toUpperCase(Locale.ROOT),x.bonus(),x.effectiveDate().toString(),x.reason());return Map.of("message","Salary change recorded");}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(){Integer n=db.queryForObject("SELECT COUNT(*) FROM employee",Integer.class),a=db.queryForObject("SELECT COUNT(*) FROM employee WHERE employment_status='ACTIVE'",Integer.class);List<Map<String,Object>> totals=db.queryForList("SELECT s.currency,ROUND(SUM(s.amount+s.bonus),2) total_compensation FROM salary_record s JOIN (SELECT employee_id,MAX(id) id FROM salary_record GROUP BY employee_id) l ON l.id=s.id JOIN employee e ON e.id=s.employee_id WHERE e.employment_status='ACTIVE' GROUP BY s.currency ORDER BY s.currency");return Map.of("employees",n==null?0:n,"activeEmployees",a==null?0:a,"compensationByCurrency",totals);}
 @GetMapping("/analytics/countries") public List<Map<String,Object>> countries(){return analytics("country");}
 @GetMapping("/analytics/departments") public List<Map<String,Object>> departments(){return analytics("department");}
 private List<Map<String,Object>> analytics(String g){return db.queryForList("SELECT e."+g+" category,s.currency,COUNT(*) employees,ROUND(AVG(s.amount),2) average_salary,MIN(s.amount) minimum_salary,MAX(s.amount) maximum_salary FROM employee e JOIN salary_record s ON s.id=(SELECT id FROM salary_record WHERE employee_id=e.id ORDER BY effective_date DESC,id DESC LIMIT 1) WHERE e.employment_status='ACTIVE' GROUP BY e."+g+",s.currency ORDER BY e."+g+",s.currency");}
 private void require(long id){Integer n=db.queryForObject("SELECT COUNT(*) FROM employee WHERE id=?",Integer.class,id);if(n==null||n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found");}
}
